 temperatura:+(s.ac?23+Math.random():27+Math.random()).toFixed(1),umidade:Math.round(55+Math.random()*4),
 potencia_w:s.potencia,energia_kwh:s.energia,ac:{ligado:s.ac},carga:{modo:s.modo}};
return msg;

