if(!s.online) return offline();
s.ac=false; global.set('campus',s);
msg.statusCode=200; msg.payload={ok:true,room_id:101,ac:'cortado'}; return msg;

const H={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'Content-Type, Accept','Access-Control-Allow-Methods':'GET,POST,OPTIONS'};
msg.headers=H;
const s=global.get('campus')||{ocupada:false,ac:true,modo:'AUTO',potencia:1450,energia:12.34,online:true,ts:Date.now(),oled:''};
const offline=()=>{msg.statusCode=503;msg.payload={erro:'dispositivo offline'};return msg;};
const cmd=String((msg.payload||{}).comando||'').toUpperCase();
if(!['ON','OFF','AUTO'].includes(cmd)){msg.statusCode=400;msg.payload={erro:'comando inválido (use ON, OFF ou AUTO)'};return msg;}
if(!s.online) return offline();
s.modo=cmd; global.set('campus',s);
msg.statusCode=200; msg.payload={ok:true,modo:cmd}; return msg;

const H={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'Content-Type, Accept','Access-Control-Allow-Methods':'GET,POST,OPTIONS'};
msg.headers=H;
const s=global.get('campus')||{ocupada:false,ac:true,modo:'AUTO',potencia:1450,energia:12.34,online:true,ts:Date.now(),oled:''};
const offline=()=>{msg.statusCode=503;msg.payload={erro:'dispositivo offline'};return msg;};
const t=String((msg.payload||{}).mensagem||'').trim();
if(!t||t.length>64){msg.statusCode=400;msg.payload={erro:'mensagem vazia ou maior que 64 caracteres'};return msg;}
if(!s.online) return offline();
s.oled=t; global.set('campus',s);
msg.statusCode=200; msg.payload={ok:true,exibindo:t}; return msg;

